/**
 * Diagramas de fluxo dos agentes — visualização somente-leitura com a estrutura REAL e
 * COMPLETA de cada workflow do n8n (todo nó real, com nome, tipo e posição reais, e toda
 * conexão real), gerada a partir do workflow publicado na instância de produção via n8n
 * MCP/API. Nada foi condensado ou hand-picked: quando um fluxo aparece grande aqui (Aurora
 * Core tem quase 300 nós, Júlia SDR tem quase 80) é porque o fluxo real é mesmo grande — o
 * visualizador (AgentFlowViewer.tsx) já suporta pan/zoom exatamente para isso. Nós do tipo
 * `stickyNote` (comentários de canvas, sem lógica e sem conexões reais) foram excluídos.
 * Cada nó tem uma `description` em linguagem simples (o que ele faz de verdade), porque o
 * nome técnico do n8n sozinho não é suficiente pra quem não construiu o fluxo entender o
 * que acontece.
 *
 * Chave = agent_key (mesmo identificador de FIXED_N8N_PROMPT_KEY em SettingsSistemaAuroraAgentes.tsx).
 * Sem entrada aqui para uma chave = usa DEFAULT_FLOW (estrutura real do agente "Diretoria"
 * / CEO AI — Financeiro, Marketing, Organização, Pesquisa, Atendimento e Agente Comercial
 * seguem essa mesma forma real no n8n hoje, só trocando o nome do agente e das ferramentas).
 */

export interface FlowNode {
  id: string;
  /** Nome real do nó, exatamente como aparece no n8n. */
  name: string;
  /** Tipo real do nó no n8n (ex: "n8n-nodes-base.webhook") — decide o ícone e a cor mostrados. */
  nodeType: string;
  /** O que esse nó faz, em linguagem simples — não é o nome técnico do n8n. */
  description: string;
  position: [number, number];
}

export interface FlowEdge {
  from: string;
  to: string;
  label?: string;
}

export interface AgentFlowDiagram {
  nodes: FlowNode[];
  edges: FlowEdge[];
}

